namespace ChilliCream.Analyzers.Tests;

public sealed partial class RemoveRedundantTypeArgumentsAnalyzerTests
{
    [Fact]
    public async Task Analyze_Should_ReportNothing_When_AutoGeneratedHeader()
    {
        // arrange
        const string source =
            """
            // <auto-generated/>
            using System.Threading.Tasks;

            class C
            {
                void M()
                {
                    var task = Task.FromResult<string>("x");
                }
            }
            """;

        // act & assert
        await VerifyAsync(source);
    }

    [Fact]
    public async Task Analyze_Should_ReportNothing_When_CommentInTypeArgumentList()
    {
        // arrange
        const string source =
            """
            class C
            {
                static T Id<T>(T value) => value;

                void M()
                {
                    Id</* number */ int>(1);
                }
            }
            """;

        // act & assert
        await VerifyAsync(source);
    }

    [Fact]
    public async Task Analyze_Should_ReportNothing_When_DirectiveInTypeArgumentList()
    {
        // arrange
        const string source =
            """
            class C
            {
                static T Id<T>(T value) => value;

                void M()
                {
                    Id<
            #if true
                    int
            #endif
                    >(1);
                }
            }
            """;

        // act & assert
        await VerifyAsync(source);
    }

    [Fact]
    public async Task Analyze_Should_ReportNothing_When_DocumentationCommentInTypeArgumentList()
    {
        // arrange
        const string source =
            """
            class C
            {
                static T Id<T>(T value) => value;

                void M()
                {
                    Id</** number */ int>(1);
                }
            }
            """;

        // act & assert
        await VerifyAsync(source);
    }

    [Fact]
    public async Task Analyze_Should_ReportNothing_When_InvocationHasError()
    {
        // arrange
        const string source =
            """
            class C
            {
                static T Id<T>(T value) => value;

                void M()
                {
                    int number;

                    Id<int>({|CS0165:number|});
                }
            }
            """;

        // act & assert
        await VerifyAsync(source);
    }

    [Fact]
    public async Task Analyze_Should_ReportNothing_When_MethodGroup()
    {
        // arrange
        const string source =
            """
            using System;
            using System.Collections.Generic;

            class C
            {
                static T Id<T>(T value) => value;

                static void Print<T>(T value)
                {
                }

                void M(List<int> numbers)
                {
                    Func<int, int> map = Id<int>;
                    numbers.ForEach(Print<int>);
                }
            }
            """;

        // act & assert
        await VerifyAsync(source);
    }
}
